foreach ($s in $screens) {
    $ssPath = Join-Path $exportDir ($s.title + ".png")
    $htmlPath = Join-Path $exportDir ($s.title + ".html")
    
    Write-Host "Downloading $($s.title)..."
    try {
        Invoke-WebRequest -Uri $s.ss -OutFile $ssPath -TimeoutSec 30
        Invoke-WebRequest -Uri $s.html -OutFile $htmlPath -TimeoutSec 30
    } catch {
        Write-Warning "Failed to download $($s.title): $_"
    }
}
